const D = { relief: .55, density: .5, energy: .6, speed: 1, scale: 1, hue: 275, x: .5, y: .45, style: 'gem', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const t = K.t;
const spd = P.speed;

// --- mesh topology: rebuild on size / density / seed change ---
const gx = Math.max(4, Math.round(6 + P.density * 14));
const gy = Math.max(3, Math.round(gx * height / width));
const topoKey = width + 'x' + height + ':' + gx + 'x' + gy + ':' + (P.seed | 0);
if (S.topoKey !== topoKey) {
  S.topoKey = topoKey;
  const fr = i => { const s = Math.sin(i * 127.1 + (P.seed | 0) * 311.7) * 43758.5453; return s - Math.floor(s); };
  const nv = (gx + 1) * (gy + 1);
  S.gx = gx; S.gy = gy; S.nv = nv;
  S.ph = new Float32Array(nv);   // per-vertex phase
  S.pf = new Float32Array(nv);   // per-vertex freq wobble
  S.hj = new Float32Array(nv);   // per-vertex hue jitter
  for (let n = 0; n < nv; n++) { S.ph[n] = fr(n + 1) * 6.283; S.pf[n] = 0.7 + fr(n + 77) * 0.9; S.hj[n] = (fr(n + 913) - 0.5); }
  S.vx = new Float32Array(nv); S.vy = new Float32Array(nv); S.vz = new Float32Array(nv);
}
const GX = S.gx, GY = S.gy;

// --- per-vertex 3D positions (overscan so facets bleed past the frame edges) ---
const mx = width / GX, my = height / GY;                 // one-cell overscan
const cw = (width + 2 * mx) / GX, ch = (height + 2 * my) / GY;
const hAmp = (0.10 + P.relief * 0.9) * u * 0.42 + A.bass * u * 0.10;   // facet height amplitude
const jit = cw * (0.10 + P.scale * 0.14);                // xy drift amplitude
const ff = 2.4 / u;                                      // spatial feature freq
const vx = S.vx, vy = S.vy, vz = S.vz, ph = S.ph, pf = S.pf;
for (let j = 0; j <= GY; j++) {
  for (let i = 0; i <= GX; i++) {
    const n = j * (GX + 1) + i;
    const bx = -mx + i * cw, by = -my + j * ch;
    const p = ph[n], f = pf[n];
    const jx = jit * Math.sin(t * 0.5 * spd + p + i * 0.7);
    const jy = jit * Math.cos(t * 0.42 * spd + p * 1.3 + j * 0.6);
    const z = hAmp * 0.5 * (
      Math.sin(bx * ff * 1.6 * f + t * 0.7 * spd + p) +
      Math.cos(by * ff * 1.4 * f - t * 0.6 * spd + p * 0.7) +
      0.6 * Math.sin((bx + by) * ff * 0.7 - t * 0.35 * spd + p * 0.4)
    );
    vx[n] = bx + jx; vy[n] = by + jy; vz[n] = z;
  }
}

// --- rotating light + view ---
const theta = t * 0.28 * spd + P.x * 6.283 + K.section * 0.4;
const lz = 0.35 + P.y * 0.55;
let Lx = Math.cos(theta) * 0.85, Ly = Math.sin(theta) * 0.85, Lz = lz;
let Ll = Math.hypot(Lx, Ly, Lz); Lx /= Ll; Ly /= Ll; Lz /= Ll;
// half vector with view (0,0,1)
let Hx = Lx, Hy = Ly, Hz = Lz + 1; const Hl = Math.hypot(Hx, Hy, Hz); Hx /= Hl; Hy /= Hl; Hz /= Hl;

const style = P.style;
const expo = 0.55 + P.energy * 0.7 + K.intensity * 0.3;
const glintS = (0.6 + P.energy * 1.1) + A.treble * 1.2;
const hueBase = (P.hue + K.section * 14 + t * 2.2) % 360;
const secBuild = 0.74 + 0.26 * Math.sin(K.section * 0.9 + t * 0.05);

// style shading params
let shin, amb, edgeMode; // edgeMode: 0 bright hue edge, 1 white, 2 dark, 3 wire-only
if (style === 'crystal-ice') { shin = 26; amb = 0.30; edgeMode = 1; }
else if (style === 'copper') { shin = 34; amb = 0.10; edgeMode = 2; }
else if (style === 'sunset') { shin = 12; amb = 0.16; edgeMode = 0; }
else if (style === 'blueprint') { shin = 8; amb = 0.06; edgeMode = 3; }
else { shin = 18; amb = 0.16; edgeMode = 0; } // gem

push();
strokeJoin(ROUND);
const glints = [];
// draw each quad as two triangles
for (let j = 0; j < GY; j++) {
  for (let i = 0; i < GX; i++) {
    const a = j * (GX + 1) + i, b = a + 1, c = a + (GX + 1), d = c + 1;
    shadeTri(a, b, d);
    shadeTri(a, d, c);
  }
}
// batched specular glint pass (partial, additive — never full-frame)
if (glints.length && edgeMode !== 3) {
  blendMode(ADD); noStroke();
  const gs = u * 0.022 * (0.6 + P.energy);
  for (let k = 0; k < glints.length; k++) {
    const g = glints[k];
    fill(0, 0, 100, g.a);
    ellipse(g.x, g.y, gs, gs);
  }
  blendMode(BLEND);
}
pop();

function shadeTri(i1, i2, i3) {
  const ax = vx[i1], ay = vy[i1], az = vz[i1];
  const bx = vx[i2], by = vy[i2], bz = vz[i2];
  const cx2 = vx[i3], cy2 = vy[i3], cz2 = vz[i3];
  // facet normal
  let e1x = bx - ax, e1y = by - ay, e1z = bz - az;
  let e2x = cx2 - ax, e2y = cy2 - ay, e2z = cz2 - az;
  let nx = e1y * e2z - e1z * e2y;
  let ny = e1z * e2x - e1x * e2z;
  let nz = e1x * e2y - e1y * e2x;
  let nl = Math.hypot(nx, ny, nz) || 1; nx /= nl; ny /= nl; nz /= nl;
  if (nz < 0) { nx = -nx; ny = -ny; nz = -nz; }
  const diff = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
  let sp = nx * Hx + ny * Hy + nz * Hz; sp = sp > 0 ? Math.pow(sp, shin) * glintS : 0;
  const ccx = (ax + bx + cx2) / 3, ccy = (ay + by + cy2) / 3, ccz = (az + bz + cz2) / 3;
  const gval = 0.5 + 0.42 * (ccz / (hAmp + 1e-3)) + 0.15 * Math.sin(ccx * 0.011 - ccy * 0.009 + K.section);
  const hj = S.hj[i1] * 22;

  let hh, ss, bb, eh, es, eb, ew = 1;
  if (style === 'crystal-ice') {
    hh = (188 + gval * 46 + hj * 0.5) % 360;
    ss = 22 + Math.max(0, 34 - sp * 30);
    bb = Math.min(100, (35 + diff * 55) * expo * secBuild + sp * 60);
    eh = 200; es = 8; eb = 100; ew = 1.1;
  } else if (style === 'copper') {
    hh = (18 + gval * 20 + hj * 0.4 + 360) % 360;
    ss = 58 + diff * 22 - sp * 20;
    bb = Math.min(100, (14 + diff * 52) * expo * secBuild + sp * 78);
    eh = (14 - gval * 8 + 360) % 360; es = 80; eb = 22; ew = 1;
  } else if (style === 'sunset') {
    hh = (44 + (ccy / height) * 268 + hj + 360) % 360;
    ss = 66 + diff * 16;
    bb = Math.min(100, (28 + diff * 52) * expo * secBuild + sp * 42);
    eh = hh; es = 40; eb = 100; ew = 1;
  } else if (style === 'blueprint') {
    hh = 214; ss = 60 + diff * 20;
    bb = Math.min(40, 7 + diff * 12 * expo);
    eh = 196; es = 72; eb = Math.min(100, 78 + sp * 30 + diff * 20); ew = 1.2;
  } else { // gem
    hh = (hueBase + gval * 92 + hj + 720) % 360;
    ss = Math.min(100, 74 + 16 * Math.sin(gval * 6.28) - sp * 44);
    bb = Math.min(100, (20 + diff * 60) * expo * secBuild + sp * 46);
    eh = (hh + 8) % 360; es = 26; eb = 100; ew = 1.1;
  }

  const av = P.alpha;
  if (edgeMode === 3) {
    noFill();
    stroke(eh, es, eb, 92 * av / 100); strokeWeight(ew);
  } else {
    fill(hh, ss, bb, av);
    stroke(eh, es, eb, av); strokeWeight(ew);
  }
  triangle(ax, ay, bx, by, cx2, cy2);
  if (sp > 0.55 && edgeMode !== 3) glints.push({ x: ccx, y: ccy, a: Math.min(58, sp * 38) * av / 100 });
}
